L.STRINGS = {
	["120 Merchant's Favor"] = "120 de Favor Mercantil",
	["1200 Merchant's Favor"] = "1200 de Favor Mercantil",
	["1500 Merchant's Favor"] = "1500 de Favor Mercantil",
	["180 Merchant's Favor"] = "180 de Favor Mercantil",
	["200 Merchant's Favor"] = "200 de Favor Mercantil",
	["240 Merchant's Favor"] = "240 de Favor Mercantil",
	["270 Merchant's Favor"] = "270 de Favor Mercantil",
	["360 Merchant's Favor"] = "360 de Favor Mercantil",
	["60 Merchant's Favor"] = "60 de Favor Mercantil",
	["6000 Merchant's Favor"] = "6000 de Favor Mercantil",
	["90 Merchant's Favor"] = "90 de Favor Mercantil",
	["A 1.5-second cast: a 3-minute curse that hurts the player now and then when they attack. Remove it."] = "Lançamento de 1,5 segundo: uma maldição de 3 minutos que fere o jogador de vez em quando ao atacar. Remova-a.",
	["A 2-second cast, then for 6 seconds arcane energy hits everyone within 25 yards every 2 seconds, for about 140 damage each time. Ranged players, stay beyond 25 yards; melee, step out during the cast."] = "Lançamento de 2 segundos; depois, por 6 segundos, energia arcana atinge todos num raio de 25 metros a cada 2 segundos, causando cerca de 140 de dano por vez. Quem ataca à distância, fique a mais de 25 metros; quem luta corpo a corpo, afaste-se durante o lançamento.",
	["A 2-second cast: a hit, then Nature damage for a minute. Cure the poison."] = "Lançamento de 2 segundos: um golpe e depois dano de Natureza por um minuto. Cure o veneno.",
	["A 2-second cast: arcane power drains up to 200 mana from everyone within 45 yards of him."] = "Lançamento de 2 segundos: poder arcano drena até 200 de mana de todos num raio de 45 metros dele.",
	["A 3-second Shadow bolt on the tank, over and over. Interrupt it."] = "Uma seta de Sombra de 3 segundos no tanque, sem parar. Interrompa.",
	["A Better Ingredient"] = "Um ingrediente melhor",
	["A Binding Contract"] = "Contrato vinculante",
	["A Blackrock orc who can be found in one of four cells."] = "Um orc Rocha Negra que pode estar em uma de quatro celas.",
	["A Broken Trap"] = "Armadilha quebrada",
	["A Crumpled Up Note"] = "Bilhete Amassado",
	["A Crumpled Up Note, dropped by foes inside the dungeon"] = "Bilhete Amassado, saque de inimigos dentro da masmorra",
	["A Curious Pair"] = "Uma dupla curiosa",
	["A Dark Iron dwarf held for his part in the Thandol Span attacks."] = "Um anão Ferro Negro preso por participar dos ataques à Ponte Thandol.",
	["A Dull and Flat Elven Blade"] = "Lâmina Élfica Lisa e Cega",
	["A dust storm hits the whole group now and then, and he slows the tank."] = "De tempos em tempos, uma tempestade de poeira atinge o grupo todo, e ele deixa o tanque lento.",
	["A Dynamite Plan"] = "Um plano com dinamite",
	["A fallen paladin who heals himself and shields himself from harm."] = "Um paladino caído que se cura e se protege de todo mal.",
	["A Fanglord who turns into a serpent partway through the fight."] = "Um Senhor da Presa que se transforma em serpente no meio da luta.",
	["A felguard standing in the middle of the lava lake, and the hardest-hitting boss here."] = "Um guarda vil no meio do lago de lava, e o chefe que bate mais forte aqui.",
	["A Fine Mess"] = "Uma bela bagunça",
	["A Frightened Request"] = "Um pedido assustado",
	["A giant turtle in the first great pool."] = "Uma tartaruga gigante na primeira grande lagoa.",
	["A giant turtle that will not attack first; killing him is optional."] = "Uma tartaruga gigante que não ataca primeiro; matá-la é opcional.",
	["A Green Sample"] = "Uma amostra verde",
	["A Grim Fate"] = "Um destino sombrio",
	["A heavy blow that knocks the tank back."] = "Um golpe pesado que arremessa o tanque para trás.",
	["A heavy swing at everyone in front of him. Only the tank should stand there."] = "Um golpe pesado em todos à frente dele. Só o tanque deve ficar ali.",
	["A hidden elite you summon yourself."] = "Um elite oculto que você mesmo invoca.",
	["A Host of Evil"] = "A hoste do mal",
	["A huge violet raptor, the leader of Stalker's Thicket."] = "Um enorme raptor violeta, o líder do Matagal do Espreitador.",
	["A large health pool"] = "Muita vida",
	["A lightning bolt that jumps to a second player. Interrupt it."] = "Um raio que salta para um segundo jogador. Interrompa.",
	["A mage or a druid can remove his Call of the Grave before it goes off. He fears, and drains two players below half health."] = "Um mago ou druida pode remover o Chamado do Túmulo dele antes que faça efeito. Ele amedronta e, abaixo de metade da vida, drena dois jogadores.",
	["A mage quest. The Obsidian Sentinel inside Uldaman carries the power source."] = "Missão de mago. A Sentinela de Obsidiana, dentro de Uldaman, carrega a fonte de energia.",
	["A mage trainer in a capital"] = "Um instrutor de magos numa capital",
	["A magic debuff on the tank: around 65 Arcane damage every 2 seconds for 10 seconds. Dispel it."] = "Um efeito mágico negativo no tanque: cerca de 65 de dano Arcano a cada 2 segundos por 10 segundos. Dissipe-o.",
	["A magic dispel removes his Shadow Word: Pain."] = "Uma dissipação de Magia remove a Palavra Sombria: Dor dele.",
	["A massive plant creature; optional."] = "Uma enorme criatura vegetal; opcional.",
	["A Moon-Kissed Blade"] = "Uma lâmina beijada pela lua",
	["A murloc chieftain in his shrine. His followers run for help when they are low on health, so finish them off."] = "Um chefe murloc em seu santuário. Os seguidores dele fogem em busca de ajuda quando estão com pouca vida, então acabe com eles.",
	["A naga sorceress in a side cavern off the pool; optional."] = "Uma feiticeira naga numa caverna lateral junto à lagoa; opcional.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: Jordan's Smithing Hammer, picked up from Jordan's Hammer in the courtyard. The rest: Whitestone Oak Lumber in the Deadmines, the Kor Gem in Blackfathom Deeps and Jordan's ore shipment in Loch Modan."] = "Uma missão de paladino para humanos e anões, com partes em vários lugares. Aqui: o Martelo de Ferreiro de Jardel, recolhido do Martelo de Jardel no pátio. O resto: a Madeira de Carvalho de Pedralva nas Minas Mortas, a Gema Kor nas Profundezas Negras e o Carregamento de Minério do Jardel em Loch Modan.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: Whitestone Oak Lumber, which the Goblin Woodcarvers drop. The rest: Jordan's Smithing Hammer in Shadowfang Keep, the Kor Gem in Blackfathom Deeps and Jordan's ore shipment in Loch Modan."] = "Uma missão de paladino para humanos e anões, com partes em vários lugares. Aqui: a Madeira de Carvalho de Pedralva, que os Goblins Entalhadores deixam cair. O resto: o Martelo de Ferreiro de Jardel na Bastilha da Presa Negra, a Gema Kor nas Profundezas Negras e o Carregamento de Minério do Jardel em Loch Modan.",
	["A patrol"] = "Uma patrulha",
	["A Pawn on the Eternal Board"] = "Um peão no tabuleiro eterno",
	["A pillar of flame where a player stands (3-second cast): Fire damage, then more every 3 seconds for 9 seconds. Step out of it."] = "Um pilar de chamas onde um jogador está (lançamento de 3 segundos): dano de Fogo e mais dano a cada 3 segundos por 9 segundos. Saia dele.",
	["A player takes more Physical damage for 10 minutes (2-second cast). A mage or a druid can remove it."] = "Um jogador sofre mais dano Físico por 10 minutos (lançamento de 2 segundos). Um mago ou um druida pode remover a maldição.",
	["A Portable Power Source"] = "Fonte de energia portátil",
	["A priest or a shaman can remove his Bloodlust."] = "Um sacerdote ou xamã pode remover a Sede de Sangue dele.",
	["A quilboar geomancer close to the Kraul's entrance."] = "Um geomante javatusco perto da entrada do Urzal.",
	["A raid new in WoW: Forever, on Mount Hyjal. Its bosses and loot are not known yet."] = "Uma raide inédita do WoW: Forever, no Monte Hyjal. Os chefes e o saque ainda não são conhecidos.",
	["A raid new in WoW: Forever. Its bosses and loot are not known yet."] = "Uma raide inédita do WoW: Forever. Os chefes e o saque ainda não são conhecidos.",
	["A rare bat in a small recess of the bat cave near Charlga Razorflank: not every run meets it."] = "Um morcego raro num pequeno recesso da caverna dos morcegos, perto de Charlga Talhaflanco: nem toda incursão o encontra.",
	["A rare bat, not there on every run. When it is, it waits in a small recess in the wall of the bat cave near Charlga Razorflank."] = "Um morcego raro, que não aparece em toda incursão. Quando aparece, fica num pequeno recesso na parede da caverna dos morcegos, perto de Charlga Talhaflanco.",
	["A rare spawn: not every run meets him."] = "Um raro: ele não aparece em todas as incursões.",
	["A rare spawn: not every run meets him. At 15% health he runs for help."] = "Um raro: ele não aparece em todas as incursões. Com 15% de vida, ele foge em busca de ajuda.",
	["A rare. A Stone Rumbler fights with him; interrupt his Lightning Bolt, and finish him before he runs for help at 15% health."] = "Um raro. Um Estrondor de Pedra luta com ele; interrompa o Raio dele e acabe com ele antes que fuja em busca de ajuda com 15% da vida.",
	["A rare. He calls two Burning Servants; interrupt his Fireball, and a priest or a shaman can remove his fire shield."] = "Um raro. Ele evoca dois Serviçais Incandescentes; interrompa a Bola de Fogo dele, e um sacerdote ou xamã pode remover o escudo de fogo dele.",
	["A rare. He cuts the tank's armour by three quarters, and at 15% health runs for help: finish him first."] = "Um raro. Ele reduz a armadura do tanque em três quartos e, com 15% de vida, foge em busca de ajuda: acabe com ele antes disso.",
	["A Reliquary of Purity"] = "Relicário da Pureza",
	["A satyr on the walkway above Jergosh's chamber."] = "Um sátiro na passarela acima da câmara de Jergosh.",
	["A Searing Blade warlock; clear the cultists around him first."] = "Um bruxo da Lâmina Calcinante; elimine primeiro os cultistas ao redor dele.",
	["A Shifty Merchant"] = "Comerciante ardiloso",
	["A Shred of Hope"] = "Um fiapo de esperança",
	["A Sign of Hope"] = "Um sinal de esperança",
	["A slow heal (3.5 seconds) on himself or an ally. Interrupt it."] = "Uma cura lenta (3,5 segundos) em si mesmo ou em um aliado. Interrompa.",
	["A Stone Rumbler fights at his side; interrupt his Lightning Bolt."] = "Um Estrondor de Pedra luta ao lado dele; interrompa o Raio dele.",
	["A Stone Rumbler stands with him and fights at his side."] = "Um Estrondor de Pedra fica com ele e luta ao seu lado.",
	["A storm of dust that hits the group for about 160 to 330 nature damage. Healers, be ready for it."] = "Uma tempestade de poeira que causa cerca de 160 a 330 de dano de Natureza ao grupo. Curadores, fiquem atentos.",
	["A Taste of Flame"] = "O gosto das chamas",
	["A test of the tank: he hits hard, disarms, and his Unholy Frenzy speeds his attacks by 75% for 20 seconds. Purge or dispel the frenzy, and tanks should bring a shield."] = "Um teste para o tanque: ele bate forte, desarma, e o Frenesi Profano dele acelera os ataques em 75% por 20 segundos. Use Expurgo ou dissipe o frenesi; tanques devem levar um escudo.",
	["A threshadon in the underwater cave; optional. He only melees."] = "Um manguadonte na caverna submersa; opcional. Ele só ataca corpo a corpo.",
	["A thunder lizard in the water; killing him is optional."] = "Um lagarto trovejante na água; matá-lo é opcional.",
	["A Titan dig site above Whelgar's Excavation, caught out of time, where the Titans' constructs answer to no one now. Inside: the Lost Marsh, Stalker's Thicket, the Site of the Guardian and the Lost Dig Site."] = "Um sítio de escavação titânico acima do Sítio de Escavação de Whelgar, preso fora do tempo, onde os constructos dos Titãs já não obedecem a ninguém. Lá dentro: o Charco Perdido, o Matagal do Espreitador, o Sítio do Guardião e o Sítio de Escavação Perdido.",
	["A titan site hidden in Un'Goro Crater, guarding secrets of the makers among the crater's dinosaurs."] = "Um sítio titânico escondido na Cratera Un'Goro, que guarda segredos dos Criadores entre os dinossauros da cratera.",
	["A Titan vault buried under the Badlands, where Dark Iron dwarves and troggs dig for the secrets of the earthen, and the stone keeper Archaedas guards the deepest hall."] = "Uma câmara titânica soterrada sob os Ermos, onde anões Ferro Negro e troggs escavam em busca dos segredos dos terranos, e o guardião de pedra Arkhaedas protege o salão mais profundo.",
	["A treant twisted by fel magic, among the Suffused Treants in the streets."] = "Um arvoroso deturpado por magia vil, entre os Arvorosos Impregnados nas ruas.",
	["A trogg brute on the main path; a straightforward fight if no other packs join in."] = "Um trogg brutamontes no caminho principal; luta simples, desde que nenhum outro bando se junte a ele.",
	["A troll city that sank into the ocean long ago has risen again, and naga, pirates and stranger things from the deep have claimed its streets."] = "Uma cidade troll que afundou no oceano há muito tempo ressurgiu, e nagas, piratas e coisas ainda mais estranhas vindas das profundezas tomaram suas ruas.",
	["A Twilight's Hammer shaman patrolling the tunnels."] = "Um xamã do Martelo do Crepúsculo que patrulha os túneis.",
	["A vast cavern under Desolace, sacred to the centaur, where Princess Theradras, daughter of Therazane, has fouled the waters and the resting place of Zaetar."] = "Uma vasta caverna sob Desolação, sagrada para os centauros, onde a Princesa Theradras, filha de Therazane, conspurcou as águas e o local de descanso de Zaetar.",
	["A Vengeful Fate"] = "Um destino vingativo",
	["A Visit to Gregan"] = "Uma visita a Gregan",
	["A ward closes his cave. Kill the two Death's Head Ward Keepers standing in front of it: the ward goes down when both are dead."] = "Uma barreira fecha a caverna dele. Mate os dois Guardiões da Cabeça da Morte que estão diante dela: a barreira cai quando os dois estiverem mortos.",
	["A ward seals his cave: kill the two Death's Head Ward Keepers in front of it to bring it down."] = "Uma barreira sela a caverna dele: mate os dois Guardiões da Cabeça da Morte diante dela para derrubá-la.",
	["A warlock quest. The 3 Soran'ruk Fragments drop from Twilight Acolytes here; the Large Soran'ruk Fragment comes from Shadowfang Darksouls in Shadowfang Keep."] = "Uma missão de bruxo. Os 3 Fragmentos de Soran'ruk caem dos Acólitos do Crepúsculo aqui; o Fragmento Grande de Soran'ruk vem dos Almanegras Presa Negra, na Bastilha da Presa Negra.",
	["A way to remove a curse or cure a disease comes in handy. Otherwise an easy fight: clear the room before the pull."] = "Ter como remover maldições ou curar doenças ajuda bastante. Fora isso, é uma luta fácil: limpe a sala antes de puxar o chefe.",
	["A white crocolisk of the marsh."] = "Um crocolisco branco do charco.",
	["Abandoned Hope"] = "Esperança abandonada",
	["Abominable Creatures"] = "Criaturas Abomináveis",
	["Abominable Head"] = "Cabeça Abominável",
	["About every 20 seconds he fears up to three players near him: a shaman's Tremor Totem helps. Late in the fight he enrages."] = "A cada 20 segundos, mais ou menos, ele amedronta até três jogadores perto dele: o Totem Sísmico de um xamã ajuda. No fim da luta, ele se enfurece.",
	["About every 20 seconds he roars and fears up to three players near him. A shaman's Tremor Totem helps."] = "A cada 20 segundos, mais ou menos, ele ruge e amedronta até três jogadores perto dele. O Totem Sísmico de um xamã ajuda.",
	["About one run in three, one of the graveyard's three rares stands at one of six places: Azshir the Sleepless, the Fallen Champion or Ironspine."] = "Em cerca de uma a cada três incursões, um dos três raros do cemitério aparece em um de seis pontos: Ashir, o Insone, o Campeão Caído ou Espinha de Ferro.",
	["About one run in three, one of the graveyard's three rares stands at one of the six places on the map: Azshir the Sleepless, Fallen Champion or Ironspine."] = "Em cerca de uma a cada três incursões, um dos três raros do cemitério aparece em um dos seis pontos do mapa: Ashir, o Insone, Campeão Caído ou Espinha de Ferro.",
	["Above and Beyond"] = "Acima e além",
	["Accept Rig Wars from Nogg first; you need not finish it. If Nogg no longer offers Rig Wars, abandon this quest and Rig Wars comes back. Leads to Gnomer-gooooone!, the goblins' transporter to Gnomeregan."] = "Aceite primeiro Guerra dos robôs com Nogg; não é preciso concluí-la. Se Nogg não oferecer mais Guerra dos robôs, abandone esta missão e Guerra dos robôs volta a aparecer. Leva a E lá vamos nós!, o transportador dos goblins para Gnomeregan.",
	["Acid Splash hurts everyone near him over time. Interrupt his heal below half health; at 15% he runs for help."] = "Borrifo de Ácido fere todos por perto ao longo do tempo. Interrompa a cura dele abaixo de metade da vida; com 15%, ele foge em busca de ajuda.",
	["Advisor Belgrum"] = "Conselheiro Belgrum",
	["Advisor Belgrum, Hall of Explorers, Ironforge"] = "Conselheiro Belgrum, Salão dos Exploradores, Altaforja",
	["Afadra Dunwall, Ironforge"] = "Afadra Dunwall, Altaforja",
	["After 60 seconds, Shadow damage to the player (2-second cast). A mage or a druid can remove it before then."] = "Após 60 segundos, dano de Sombra ao jogador (lançamento de 2 segundos). Um mago ou druida pode remover a maldição antes disso.",
	["After a 3-second cast, a beam comes out in front of it for 6 seconds and hits four times a second. Get out of its path as soon as the cast starts."] = "Após um lançamento de 3 segundos, um feixe sai à sua frente por 6 segundos e atinge quatro vezes por segundo. Saia do caminho dele assim que o lançamento começar.",
	["After the fight, open the room's vaults: about 24 Dwarven Heirlooms for Important Heirlooms, and the stone tablet that starts The Treaty of Understanding."] = "Depois da luta, abra os cofres da sala: cerca de 24 Heranças Anãs para Heranças Importantes e a tabuleta de pedra que inicia O Tratado de Entendimento.",
	["After the fight, open the vaults of the room: about 24 Dwarven Heirlooms for Important Heirlooms, and the tablet of The Treaty of Understanding."] = "Depois da luta, abra os cofres da sala: cerca de 24 Heranças Anãs para Heranças Importantes e a tabuleta de O Tratado de Entendimento.",
	["Agmond's Fate"] = "O destino de Agmundo",
